/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect } from 'react'
import { Steps, Row, Col } from 'antd'
import StyleWrapper from './styleWrapper.style'
import { size } from 'lodash'
const { Step } = Steps

export default function SubStepWrapper ({ children, current, newSteps }) {
  const [steps, updateSteps] = useState([
    {
      code: 'package',
      title: 'Package info'
    },
    {
      code: 'validation',
      title: 'Data validation'
    }
  ])
  useEffect(() => {
    let modifiedSteps = [...steps]
    if (size(newSteps) > 0) {
      for (const item in newSteps) {
        if (item === 'provider') {
          if (newSteps[item]) {
            const checkProviderItem = modifiedSteps.find((stepItem) => stepItem.code === 'provider') || {}
            if (size(checkProviderItem) === 0) {
              modifiedSteps = [...modifiedSteps, { code: 'provider', title: 'Provider UI Config' }]
            }
          } else {
            modifiedSteps = modifiedSteps.filter(item => item.code !== 'provider')
          }
        } else if (item === 'endorsement') {
          if (newSteps[item]) {
            const checkEndorsementItem = modifiedSteps.find((stepItem) => stepItem.code === 'endorsement') || {}
            if (size(checkEndorsementItem) === 0) {
              modifiedSteps = [...modifiedSteps, { code: 'endorsement', title: 'Endorsement UI Config' }]
            }
          } else {
            modifiedSteps = modifiedSteps.filter(item => item.code !== 'endorsement')
          }
        }
      }
      updateSteps(modifiedSteps)
    }
  }, [newSteps])
  return (
    <StyleWrapper stepLength={steps.length}>
      <Row type='flex' justify='center'>
        <Col span={24}>
          <Steps current={current}>
            {steps.map(item => (
              <Step key={item.title} title={item.title} />
            ))}
          </Steps>
          <div className='steps-content'>
            {children}
          </div>
        </Col>
      </Row>
    </StyleWrapper>
  )
}
