import React, { Component } from 'react'
import StepWrapper from '../components/Step'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import { Form, Row, Col, Button, notification, Card, Spin } from 'antd'
import { get } from 'lodash'
import dataValidationActions from '../../../../../../redux/productConfig/actions'
import DataValidationFieldWrapper from '../components/DataValidation'
import Step3Wrapper from '../index'
import { ButtonSection, BodyStyleWrapper } from './index.style'
import { traceValidation } from './commanFunction'
import { StateProvider } from '../components/DataValidation/store'

const {
  resetProductConfigRedux,
  getAllProductValidations,
  addValidation
} = dataValidationActions
class DataValidation extends Component {
  state = {
    productAttributes: [],
    validationData: [],
    step1Data: {},
    packageData: {},
    initialData: [],
    newStep: {
      provider: false,
      endorsement: false
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      productValidation,
      productValidationMesage,
      validationCreatedMessage
    } = nextProps
    if (validationCreatedMessage === 'success') {
      notification.success({
        message: 'Success',
        description: 'Validations created successfully'
      })
      this.props.resetProductConfigRedux(['addProductDataValidation'])
      let url = '/product-config/create-product/3'
      if (get(this.state.newStep, 'provider')) {
        url = '/product-config/create-product/3/provider'
      } else if (get(this.state.newStep, 'endorsement')) {
        url = '/product-config/create-product/3/generic-endorsement-form'
      }
      nextProps.history.push({
        pathname: url,
        state: {
          formName: 'validation-table',
          formData: {
            step1Data: this.state.step1Data,
            step2Data: this.state.productAttributes,
            packageData: this.state.packageData
          }
        }
      })
    }
    if (validationCreatedMessage !== 'success' && validationCreatedMessage !== undefined) {
      notification.error({
        message: 'Error',
        description: 'Validations not created '
      })
      this.props.resetProductConfigRedux(['addProductDataValidation'])
    }
    if (productValidationMesage === 'success') {
      this.setState({
        validationData: get(productValidation, 'data.details', [])
      })
      this.props.resetProductConfigRedux(['getAllProductValidationMessage'])
    }
  }

  componentDidMount () {
    const { location } = this.props
    const formName = get(location, 'state.formName', '')
    switch (formName) {
      case 'providerPage':
      case 'package-info': {
        const step1Data = get(location, 'state.formData.step1Data', {})
        const step2Data = get(location, 'state.formData.step2Data', [])
        const packageData = get(location, 'state.formData.packageData', {})
        const initialData = get(location, 'state.formData.initialData', [])
        const newStep = {
          provider: get(packageData, 'document_generation_source') === 'provider' || get(packageData, 'policy_number_source') === 'provider',
          endorsement: get(packageData, 'has_endorsement_flow')
        }
        this.setState({
          initialData,
          step1Data,
          productAttributes: step2Data,
          packageData,
          newStep
        })
        this.props.getAllProductValidations()
      }
        break
      default: {
        this.props.history.push({
          pathname: '/product-config/create-product/1'

        })
      }
    }
  }

  handlePreviousPage = () => {
    const { packageData, step1Data, productAttributes, initialData } = this.state
    const { history } = this.props
    history.push({
      pathname: '/product-config/create-product/3/package-info',
      state: {
        formName: 'validation-table',
        formData: {
          initialData: initialData,
          step1Data: step1Data,
          step2Data: productAttributes,
          packageData: packageData
        }
      }
    })
  }

  handleSubmitValidationData = () => {
    const { productAttributes, step1Data, packageData } = this.state
    const endorsementTableCheck = get(packageData, 'has_endorsement_flow', false)
    let newData = []
    if (endorsementTableCheck) {
      newData = traceValidation(productAttributes)
    } else {
      const attributes = productAttributes.filter(item => item.attribute_type === 'creation')
      newData = traceValidation(attributes)
    }
    const validations = newData.data
    if (validations.length > 0) {
      const productCode = get(step1Data, 'code', '')
      const packageCode = get(packageData, 'code', '')
      this.props.addValidation({
        query: {
          productCode: productCode,
          packageCode: packageCode
        },
        body: validations
      })
    }
  }

  render () {
    const { productAttributes, validationData, packageData, initialData, newStep } = this.state
    const policyCreationData = productAttributes.length > 0 ? productAttributes.filter(item => item.attribute_type === 'creation') : []
    const endorsementTableCheck = get(packageData, 'has_endorsement_flow', false)
    const endorsementCreationData = endorsementTableCheck && productAttributes.length > 0 ? productAttributes.filter(item => item.attribute_type !== 'creation') : []
    const { validationAddLoading, validationAddError } = this.props

    return (
      <Step3Wrapper>
        <StepWrapper
          current={1}
          newSteps={newStep}
        >
          <Spin spinning={productAttributes.length === 0 && validationData.length === 0} loading='Loading Validation Tables....'>
            <BodyStyleWrapper>
              <Row type='flex'>
                <Col span={24}>
                  <Card className='card'>
                    <Row type='flex'>
                      <Col span={24}>
                        <h3 className='label'><b>Policy Creation Validation</b></h3>
                      </Col>
                      <Col span={24}>
                        <StateProvider>
                          <DataValidationFieldWrapper
                            attributesData={policyCreationData}
                            productAttributes={policyCreationData}
                            validationData={validationData}
                            intialData={initialData}
                            packageName={get(packageData, 'code', '')}
                          />
                        </StateProvider>
                      </Col>
                    </Row>
                  </Card>
                </Col>
                <Col span={24}>
                  <Card className='card Lower'>
                    <Row type='flex'>
                      <Col span={24}>
                        <h3 className='label'><b>Endorsement Validation</b></h3>
                      </Col>
                      <Col span={24}>
                        <StateProvider>
                          <DataValidationFieldWrapper
                            attributesData={productAttributes}
                            productAttributes={endorsementCreationData}
                            validationData={validationData}
                            intialData={initialData}
                            packageName=''
                          />
                        </StateProvider>
                      </Col>
                    </Row>
                  </Card>
                </Col>

              </Row>
            </BodyStyleWrapper>
          </Spin>
          <ButtonSection>
            <Row type='flex' justify='center' gutter={30}>
              <Col>
                <Button onClick={this.handlePreviousPage}>Previous</Button>
              </Col>
              <Col>
                <Button
                  type='primary'
                  // disabled={this.submitValidation()}
                  loading={validationAddLoading && !validationAddError}
                  onClick={this.handleSubmitValidationData}
                >
                  {get(newStep, 'provider') ? 'Next' : 'Submit'}
                </Button>
              </Col>
            </Row>
          </ButtonSection>
        </StepWrapper>
      </Step3Wrapper>
    )
  }
}
DataValidation.defaultProps = {
  productValidation: {
    data: {
      details: []
    },
    message: '',
    success: false
  },
  validationCreatedMessage: undefined,
  validationAddLoading: false,
  validationAddError: false,
  productValidationMesage: undefined
}
DataValidation.propTypes = {
  productValidationMesage: PropTypes.string,
  productValidation: PropTypes.shape({
    data: PropTypes.shape({
      details: PropTypes.arrayOf(PropTypes.object)
    }),
    message: PropTypes.string,
    success: PropTypes.bool
  }),
  validationAddLoading: PropTypes.bool,
  validationAddError: PropTypes.bool
}
const WrapperDataValidation = Form.create()(DataValidation)

export default connect(
  state => ({
    productValidation: state.ProductConfigurable.getAllProductValidation,
    productValidationMesage: state.ProductConfigurable.getAllProductValidationMessage,
    validationCreatedMessage: state.ProductConfigurable.addProductDataValidation,
    validationAddLoading: state.Loading.ADD_DATA_VALIDATION,
    validationAddError: state.Error.ADD_DATA_VALIDATION
  }), {
    getAllProductValidations,
    resetProductConfigRedux,
    addValidation
  }
)(WrapperDataValidation)
